/* =====================================================================
   CONTROLE DE ESTOQUE - KITS DE ONBOARDING
   Script de criacao do banco de dados (SQL Server)
   ===================================================================== */

if db_id('ControleEstoqueDB') is null
    create database ControleEstoqueDB
go

use ControleEstoqueDB
go

/* =====================================================================
   TABELAS
   ===================================================================== */

create table Usuarios (
    Id          int identity(1,1) not null primary key,
    NomeUsuario varchar(50)  not null unique,
    SenhaHash   varchar(200) not null,
    CriadoEm    datetime     not null
)
go

create table Departamentos (
    Id          int         not null primary key,
    Nome        varchar(60) not null,
    CentroCusto varchar(20) null
)
go

-- Cada produto tem o seu estoque (quantidade que pode ir para os kits)
create table Produtos (
    Id         int            not null primary key,
    Nome       varchar(60)    not null,
    Categoria  varchar(30)    not null,
    Descricao  varchar(200)   null,
    Foto       varbinary(max) null,
    Quantidade int not null default 0 check (Quantidade >= 0)
)
go

-- Colaboradores (entram no sistema com o funcional e a senha)
create table Colaboradores (
    Id             int            not null primary key,
    Nome           varchar(80)    not null,
    Funcional      char(7)        not null unique check (Funcional not like '%[^0-9]%'),
    Email          varchar(80)    not null,
    DepartamentoId int            not null foreign key references Departamentos(Id),
    DataAdmissao   datetime       not null,
    SenhaHash      varchar(200)   not null,
    Foto           varbinary(max) null
)
go

-- Mestre: o kit de onboarding de um colaborador (no maximo um kit por colaborador)
create table Kits (
    Id            int identity(1,1) not null primary key,
    ColaboradorId int          not null unique foreign key references Colaboradores(Id),
    DataMontagem  datetime     not null,
    Situacao      varchar(20)  not null check (Situacao in ('Montado', 'Entregue')),
    Observacao    varchar(200) null,
    DataEntrega   datetime     null
)
go

-- Detalhe: os produtos que compoem o kit
create table KitItens (
    Id         int identity(1,1) not null primary key,
    KitId      int not null foreign key references Kits(Id),
    ProdutoId  int not null foreign key references Produtos(Id),
    Quantidade int not null check (Quantidade > 0),
    unique (KitId, ProdutoId)
)
go


/* =====================================================================
   STORED PROCEDURES GENERICAS (usadas pelo PadraoDAO)
   ===================================================================== */

create procedure spDelete
(
    @id     int,
    @tabela varchar(max)
)
as
begin
    declare @sql varchar(max);
    set @sql = ' delete ' + @tabela +
               ' where id = ' + cast(@id as varchar(max))
    exec(@sql)
end
go

create procedure spConsulta
(
    @id     int,
    @tabela varchar(max)
)
as
begin
    declare @sql varchar(max);
    set @sql = 'select * from ' + @tabela +
               ' where id = ' + cast(@id as varchar(max))
    exec(@sql)
end
go

create procedure spListagem
(
    @tabela varchar(max),
    @ordem  varchar(max)
)
as
begin
    exec('select * from ' + @tabela + ' order by ' + @ordem)
end
go

create procedure spProximoId
(@tabela varchar(max))
as
begin
    exec('select isnull(max(id) +1, 1) as MAIOR from ' + @tabela)
end
go

/* =====================================================================
   USUARIOS (administradores)
