create procedure spInsert_Usuarios
(
    @nomeUsuario varchar(max),
    @senhaHash   varchar(max),
    @criadoEm    datetime
)
as
begin
    insert into Usuarios (NomeUsuario, SenhaHash, CriadoEm)
