end
go

create procedure spBuscaUsuario
(
    @nomeUsuario varchar(max)
)
as
begin
    select * from Usuarios where NomeUsuario = @nomeUsuario
end
go

create procedure spContaUsuarios
as
begin
    select count(1) from Usuarios
end
