/* =====================================================================
   PRODUTOS
   ===================================================================== */

create procedure spInsert_Produtos
(
    @id        int,
    @nome      varchar(max),
    @categoria varchar(max),
    @descricao varchar(max),
    @foto      varbinary(max)
)
as
begin
    insert into Produtos (Id, Nome, Categoria, Descricao, Foto, Quantidade)
    values (@id, @nome, @categoria, @descricao, @foto, 0)
end
go

create procedure spUpdate_Produtos
(
    @id        int,
    @nome      varchar(max),
    @categoria varchar(max),
    @descricao varchar(max),
    @foto      varbinary(max)
)
as
begin
    update Produtos set
        Nome = @nome,
        Categoria = @categoria,
        Descricao = @descricao,
        Foto = @foto
    where Id = @id
end
go

-- le o estoque do produto com updlock (trava a linha ate o fim da transacao)
create procedure spLeEstoqueProduto
(
    @id int
)
as
begin
    select Id, Nome, Quantidade
    from Produtos with (updlock, rowlock)
    where Id = @id
end
go

create procedure spSalvaEstoqueProduto
(
    @id         int,
    @quantidade int
)
as
begin
    update Produtos set Quantidade = @quantidade
    where Id = @id
end
go

