-- listagem com JOIN para exibir o nome do departamento
create procedure spListagem_Colaboradores
(
    @tabela varchar(max),
    @ordem  varchar(max)
)
as
begin
    select Colaboradores.*, Departamentos.Nome as NomeDepartamento
    from Colaboradores
    inner join Departamentos on Colaboradores.DepartamentoId = Departamentos.Id
    order by Colaboradores.Nome
end
go

create procedure spConsultaColaboradorPorFuncional
(
    @funcional varchar(max)
)
as
begin
    select Colaboradores.*, Departamentos.Nome as NomeDepartamento
    from Colaboradores
    inner join Departamentos on Colaboradores.DepartamentoId = Departamentos.Id
    where Colaboradores.Funcional = @funcional
end
