/* =====================================================================
   KITS (mestre) e KITITENS (detalhe)
   ===================================================================== */

create procedure spInsert_Kits
(
    @id            int,
    @colaboradorId int,
    @dataMontagem  datetime,
    @situacao      varchar(max),
    @observacao    varchar(max),
    @dataEntrega   datetime
)
as
begin
    insert into Kits (ColaboradorId, DataMontagem, Situacao, Observacao, DataEntrega)
    values (@colaboradorId, @dataMontagem, @situacao, @observacao, @dataEntrega)
end
go

create procedure spUpdate_Kits
(
    @id            int,
    @colaboradorId int,
    @dataMontagem  datetime,
    @situacao      varchar(max),
    @observacao    varchar(max),
    @dataEntrega   datetime
)
as
begin
    update Kits set
        ColaboradorId = @colaboradorId,
        DataMontagem = @dataMontagem,
        Situacao = @situacao,
        Observacao = @observacao,
        DataEntrega = @dataEntrega
    where Id = @id
end
go

-- listagem com JOIN (colaborador e departamento) e o total de unidades do kit
create procedure spListagem_Kits
(
    @tabela varchar(max),
    @ordem  varchar(max)
)
as
begin
    select Kits.*,
           Colaboradores.Nome      as NomeColaborador,
           Colaboradores.Funcional as Funcional,
           Departamentos.Nome      as NomeDepartamento,
           (select isnull(sum(Quantidade), 0) from KitItens where KitItens.KitId = Kits.Id) as TotalUnidades
    from Kits
    inner join Colaboradores on Kits.ColaboradorId = Colaboradores.Id
    inner join Departamentos on Colaboradores.DepartamentoId = Departamentos.Id
    order by Kits.Id desc
end
go

create procedure spConsultaKitDoColaborador
(
    @colaboradorId int
)
as
begin
    select * from Kits where ColaboradorId = @colaboradorId
end
go

