(
    @id         int,
    @kitId      int,
    @produtoId  int,
    @quantidade int
)
as
begin
    insert into KitItens (KitId, ProdutoId, Quantidade)
    values (@kitId, @produtoId, @quantidade)
end
go

create procedure spUpdate_KitItens
(
    @id         int,
    @kitId      int,
    @produtoId  int,
    @quantidade int
)
as
begin
    update KitItens set
        KitId = @kitId,
        ProdutoId = @produtoId,
        Quantidade = @quantidade
    where Id = @id
end
go

create procedure spListagemItensDoKit
(
    @kitId int
)
as
begin
    select KitItens.*,
           Produtos.Nome      as NomeProduto,
           Produtos.Categoria as Categoria,
           Produtos.Foto      as FotoProduto
    from KitItens
    inner join Produtos on KitItens.ProdutoId = Produtos.Id
    where KitItens.KitId = @kitId
    order by Produtos.Nome
end
go

create procedure spDeleteItensDoKit
(
    @kitId int
)
as
begin
    delete KitItens where KitId = @kitId
end
go

/* =====================================================================
   CONSULTAS AVANCADAS (com filtros e joins)
   ===================================================================== */

-- Consulta 1: kits montados
create procedure spConsultaAvancadaKits
(
    @colaborador    varchar(max),
    @departamentoId int,
    @situacao       varchar(max),
    @dataInicial    datetime,
    @dataFinal      datetime
)
as
begin
    declare @depIni int
    declare @depFim int
    set @depIni = case @departamentoId when 0 then 0 else @departamentoId end
    set @depFim = case @departamentoId when 0 then 999999 else @departamentoId end

    select Kits.*,
           Colaboradores.Nome      as NomeColaborador,
           Colaboradores.Funcional as Funcional,
           Departamentos.Nome      as NomeDepartamento,
           (select isnull(sum(Quantidade), 0) from KitItens where KitItens.KitId = Kits.Id) as TotalUnidades
    from Kits
    inner join Colaboradores on Kits.ColaboradorId = Colaboradores.Id
    inner join Departamentos on Colaboradores.DepartamentoId = Departamentos.Id
    where (Colaboradores.Nome like '%' + @colaborador + '%' or Colaboradores.Funcional like '%' + @colaborador + '%')
      and Colaboradores.DepartamentoId between @depIni and @depFim
      and (@situacao = '' or Kits.Situacao = @situacao)
      and Kits.DataMontagem between @dataInicial and @dataFinal
    order by Kits.DataMontagem desc
end
go

-- Consulta 2: produtos usados nos kits, por departamento (dados consolidados)
create procedure spConsultaAvancadaItens
(
    @produtoId      int,
    @categoria      varchar(max),
    @departamentoId int,
    @dataInicial    datetime,
    @dataFinal      datetime
)
as
begin
    declare @prodIni int
    declare @prodFim int
    declare @depIni int
    declare @depFim int
    set @prodIni = case @produtoId when 0 then 0 else @produtoId end
    set @prodFim = case @produtoId when 0 then 999999 else @produtoId end
    set @depIni  = case @departamentoId when 0 then 0 else @departamentoId end
    set @depFim  = case @departamentoId when 0 then 999999 else @departamentoId end

    select Produtos.Nome       as NomeProduto,
           Produtos.Categoria  as Categoria,
           Departamentos.Nome  as NomeDepartamento,
           count(distinct Kits.Id)      as QtdKits,
           sum(KitItens.Quantidade)     as QtdUnidades
    from KitItens
    inner join Kits          on KitItens.KitId = Kits.Id
    inner join Produtos      on KitItens.ProdutoId = Produtos.Id
    inner join Colaboradores on Kits.ColaboradorId = Colaboradores.Id
    inner join Departamentos on Colaboradores.DepartamentoId = Departamentos.Id
    where KitItens.ProdutoId between @prodIni and @prodFim
      and (@categoria = '' or Produtos.Categoria = @categoria)
      and Colaboradores.DepartamentoId between @depIni and @depFim
      and Kits.DataMontagem between @dataInicial and @dataFinal
    group by Produtos.Nome, Produtos.Categoria, Departamentos.Nome
    order by Produtos.Nome, QtdUnidades desc
end
go

create procedure spListagemCategorias
as
begin
    select distinct Categoria from Produtos order by Categoria
end
go

/* =====================================================================
   DADOS CONSOLIDADOS (APIs e Home administrativa)
   ===================================================================== */

-- API 1: kits por departamento
create procedure spKitsPorDepartamento
(
    @dataInicial datetime,
    @dataFinal   datetime
)
as
begin
    select Departamentos.Id   as DepartamentoId,
           Departamentos.Nome as NomeDepartamento,
           count(Kits.Id) as TotalKits,
           sum(case when Kits.Situacao = 'Montado'  then 1 else 0 end) as KitsMontados,
           sum(case when Kits.Situacao = 'Entregue' then 1 else 0 end) as KitsEntregues,
           isnull(sum(Unidades.Quantidade), 0) as TotalUnidades
    from Departamentos
    inner join Colaboradores on Colaboradores.DepartamentoId = Departamentos.Id
    inner join Kits          on Kits.ColaboradorId = Colaboradores.Id
    left join (select KitId, sum(Quantidade) as Quantidade from KitItens group by KitId) as Unidades
           on Unidades.KitId = Kits.Id
    where Kits.DataMontagem between @dataInicial and @dataFinal
    group by Departamentos.Id, Departamentos.Nome
    order by TotalKits desc, Departamentos.Nome
end
go

-- API 2: produtos mais usados nos kits
create procedure spProdutosMaisUsados
(
    @top int
)
as
begin
    select top (@top)
           Produtos.Id        as ProdutoId,
           Produtos.Nome      as NomeProduto,
           Produtos.Categoria as Categoria,
           count(distinct KitItens.KitId) as QtdKits,
           sum(KitItens.Quantidade)       as QtdUnidades,
           Produtos.Quantidade            as EmEstoque
    from KitItens
    inner join Produtos on KitItens.ProdutoId = Produtos.Id
    group by Produtos.Id, Produtos.Nome, Produtos.Categoria, Produtos.Quantidade
    order by QtdUnidades desc, Produtos.Nome
end
go

-- numeros para a Home administrativa
create procedure spResumoAdmin
as
begin
    select (select count(*) from Kits)                           as TotalKits,
           (select count(*) from Kits where Situacao = 'Montado') as KitsMontados,
           (select count(*) from Colaboradores)                   as TotalColaboradores,
           (select count(*) from Colaboradores c
             where not exists (select 1 from Kits k where k.ColaboradorId = c.Id)) as ColaboradoresSemKit,
           (select count(*) from Produtos)                        as TotalProdutos
end
go

